import{_ as d,h as l,i as a,c,v as r,p as n,x as o,m as i,e as s,S as p}from"./chunks/framework.Dvtg8yj2.js";const A=JSON.parse('{"title":"Hugging Face TGI","description":"","frontmatter":{"title":"Hugging Face TGI","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/tgi.md","filePath":"llm/tgi.md","lastUpdated":1788454257000}'),h={name:"llm/tgi.md"};function u(m,e,g,T,f,P){const t=l("Mermaid");return a(),c("div",null,[e[1]||(e[1]=r('<h1 id="hugging-face-tgi" tabindex="-1">Hugging Face TGI <a class="header-anchor" href="#hugging-face-tgi" aria-label="Permalink to &quot;Hugging Face TGI&quot;">​</a></h1><div class="epigraph"><p>路由器收请求、组 batch、发 gRPC；模型服务端加载权重、做张量并行、跑 prefill 与 decode。两者不必落在同一台机器上。</p><footer>—— Hugging Face，Text Generation Inference Architecture 文档</footer></div><p>Text Generation Inference（TGI）是 Hugging Face 为开源大模型写的一套生产向推理工具箱：连续批处理、张量并行、Server-Sent Events 流式输出、OpenTelemetry 与 Prometheus、以及后来补上的 OpenAI Messages API。官方架构文档把它拆成三块——Rust 写的 router（也称 webserver）、Python 写的 model server、以及把两者拉起来的 launcher。调度在 router 里发生，GEMM 与 KV 在 model server 里发生，中间用 gRPC。本篇按这份文档写调用流，不把某一版吞吐数字写成论文结果。Hugging Face 后续已把 TGI 标为维护模式，并推荐新部署优先看 vLLM、SGLang 以及本地侧的 llama.cpp / MLX；理解 TGI，是为了看清「HTTP 服务」与「逐步解码引擎」为什么必须拆开，以及后来的引擎继承了哪些接口习惯。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自回归生成不是一次 RPC 算完。提示要 prefill，之后每步 decode 出一个 token，客户端还可能中途断开。若把「收 HTTP、做 tokenize、组 batch、跑模型、detokenize、写 SSE」塞进同一个 Python 进程，队列策略、取消语义和 GPU 内核会缠在一起：改调度就要动 CUDA，改模型就要动 HTTP。TGI 要解决的，是把延迟敏感的组批放在靠近客户端的一侧，把权重与集合通信放在靠近加速器的一侧，并用一份稳定的批次协议把两边钉住。</p><p>另一半问题是 Hub 上的模型形态。权重在 safetensors 里，结构声明在 <code>transformers</code> 的配置里，词表与 <a href="/llm/chat-template">chat template</a> 跟 tokenizer 绑定。服务端若另写一套架构注册表，每出一个新模型就要分叉。TGI 早期推动「推理引擎直接吃 <code>transformers</code> 架构」——官方索引页把这一点写成它对后续引擎的影响，而不是声称自己永远是吞吐最高的实现。</p><h3 id="维护模式不等于架构作废" tabindex="-1">维护模式不等于架构作废 <a class="header-anchor" href="#维护模式不等于架构作废" aria-label="Permalink to &quot;维护模式不等于架构作废&quot;">​</a></h3><p>维护模式的意思是：仓库仍接受小修复与文档，不再当新特性的主战场。生产上仍有大量已部署实例；OpenAI 兼容路径、SSE、连续批的调用形状，已经被 vLLM 与 SGLang 的 HTTP 层沿用。读 TGI，应把它当成一份把服务拆成 router / engine 的参考实现，而不是一份过时的 Docker 配方。</p><p><span class="marginnote">不要把 TGI 文档里的默认上限（如 <code>max-concurrent-requests=128</code>、<code>max-input-tokens=1024</code>）抄成模型能力。那是 router 的准入闸门，用来保护 KV 与 prefill 预算，与模型卡上的上下文长度不是同一个数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Launcher 负责拉起一个或多个 model server（模型按卡做张量并行时是多个 shard），再带着匹配的参数启动 router。Router 是 Rust HTTP 服务，吃两套入口：TGI 自己的 HTTP API，以及 OpenAI 的 Messages API。它做校验、tokenize、排队、调度和块分配，产出已经组好的 batch，再经 gRPC 发给 model server。Model server 用 PyTorch 加载模型，在 CUDA / ROCm 等后端上做推理，shard 之间用 NCCL 一类通信对齐 <a href="/llm/tensor-parallel">张量并行</a>。官方明确写：router 与 model server 可以部署在不同机器上。</p><p>gRPC 目前有 v2 与 v3 两套 schema，差别主要在输入分块（文本与图像）以及 paged attention 支持。启动后先做服务发现、取模型信息、健康检查，再 <code>warmup</code>：把 <code>max_input_tokens</code>、<code>max_batch_prefill_tokens</code>、<code>max_total_tokens</code>、<code>max_batch_size</code> 打进一次预热，避免第一笔真实流量才去编译核、分配 KV。之后的稳态调用是三类：<code>prefill</code> 吃新请求，<code>decode</code> 推进已缓存的 batch，<code>filter_batch</code> 在某条请求结束或客户端离开时，从 cached batch 里摘掉对应 <code>request_id</code>。</p>',12)),(a(),n(p,null,{default:o(()=>[s(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20LR%0A%20%20C%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%20HTTP%20%2F%20SSE%22%5D%20--%3E%20R%5B%22Rust%20router%22%5D%0A%20%20R%20--%3E%7C%22tokenize%20%C2%B7%20%E7%BB%84%E6%89%B9%22%7C%20G%5B%22gRPC%20prefill%20%2F%20decode%20%2F%20filter%22%5D%0A%20%20G%20--%3E%20S%5B%22Python%20model%20server%22%5D%0A%20%20S%20--%3E%20GPU%5B%22CUDA%20%2F%20ROCm%20%E7%AD%89%E5%8A%A0%E9%80%9F%E5%99%A8%22%5D%0A%20%20GPU%20--%3E%7C%22NCCL%20%E5%8F%AF%E9%80%89%22%7C%20GPU%0A%20%20S%20--%3E%20R%0A%20%20R%20--%3E%20C%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h3 id="prefill-插入时为什么要停掉当前-decode" tabindex="-1">Prefill 插入时为什么要停掉当前 decode <a class="header-anchor" href="#prefill-插入时为什么要停掉当前-decode" aria-label="Permalink to &quot;Prefill 插入时为什么要停掉当前 decode&quot;">​</a></h3><p>文档里的时序图写得很直：新请求到来时，router 向 model server 发一个新的 <code>prefill</code>；正在跑的 decode batch 会被停住，prefill 完成后再把新旧 cached batch 合并进下一次 <code>decode</code>。这不是实现疏忽，而是连续批处理的代价：prefill 与 decode 的算力画像不同，又共享同一组权重与同一条执行流。客户端中途离开时，router 调 <code>filter_batch(..., request_ids_to_keep=...)</code>，只留下还活着的序列，避免空转的 KV 继续占槽。取消语义的展开见 <a href="/llm/sse-cancel">流式输出与取消</a>。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Router 侧的调度旋钮都是为了在「等一等、组更大的 batch」和「别让已在解码的请求饿死」之间找平衡。<code>waiting-served-ratio</code>、<code>max-waiting-tokens</code>、<code>max-batch-prefill-tokens</code> 控制何时插入 prefill、一次 prefill 允许多长。块分配器则约束总 token 上限，防止 KV 把显存打满。Tokenizer 挂在 router 上（<code>--tokenizer-name</code>），长度校验发生在进 GPU 之前：非法过长的请求在 Rust 侧被拒，不必先占一次失败的 prefill。这把 <a href="/llm/serving-tokenizer-cost">tokenizer 开销</a> 从引擎热路径里拆了出来，也让校验工人数（<code>--validation-workers</code>）成为独立的 CPU 预算。</p><p>Model server 的 CLI 暴露量化（bitsandbytes / GPTQ / AWQ / FP8 等）、推测解码步数、dtype 与是否 sharded。不是每种硬件变体都实现同一组开关：官方列出 CUDA、ROCm、Intel GPU、Gaudi、Neuron、TPU（Optimum TPU）等分支，并写明特性集会因硬件与中间件而不同。量化配方不能跨变体抄。权重下载与量化是独立子命令（<code>download-weights</code>、<code>quantize</code>），与 <code>serve</code> 分开，避免服务进程在第一次请求时才去 Hub 拉盘。</p><p><span class="marginnote">TGI 把 Messages API 做成 router 开关（<code>--messages-api-enabled</code>），不是模型能力。关掉它，引擎仍能生成；打开它，只是多了一条与 OpenAI 字段对齐的 HTTP 皮。字段对齐不等于行为对齐，见 <a href="/llm/openai-compat-api">OpenAI 兼容协议</a>。</span></p><h3 id="观测与生产开关" tabindex="-1">观测与生产开关 <a class="header-anchor" href="#观测与生产开关" aria-label="Permalink to &quot;观测与生产开关&quot;">​</a></h3><p>索引页强调分布式追踪（OpenTelemetry）与 Prometheus 指标，这是它相对「脚本里 <code>model.generate</code>」真正多出来的一层。Router 还暴露 CORS、最大并发、best-of 与 stop sequence 上限。这些上限是拒绝服务与资源保护，不是采样算法本身。Watermarking、logits warper、guidance（按 schema 约束解码）属于生成侧功能，落在 engine 路径上，但调度合约仍然是 prefill / decode / filter。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>TGI 的模型覆盖以当时流行的开源结构为准（Llama、Falcon、StarCoder、BLOOM、GPT-NeoX、T5 等），新架构的第一落点已经不在这个仓库。TRT-LLM 等后端会替换 model server 与 launcher，router 仍可保留——这说明「HTTP + 组批」与「某种 CUDA 图」是可替换的。选 TGI 还是 vLLM，应看团队是否已经吃进它的运维面（镜像、指标、Hub 集成），而不是比较一篇没有版本号的延迟表。</p><p>分页注意力出现在 gRPC v3，并不意味着每一条硬件分支都有同等实现。Gaudi、Neuron、TPU 上的 KV 布局、量化与投机解码要以对应 fork 的说明为准。不要假设「TGI 支持 Paged Attention」在 Inferentia 上与 A100 上是同一句话。多卡只保证 NCCL 能同步 shard；跨节点 TP 是否划算，仍服从 <a href="/llm/pretrain-comm">通信层次</a>：decode 小 batch 时 All-Reduce 延迟会被放大。</p><p><span class="marginnote">出处停留在 Hugging Face 的 TGI 架构文档、索引页（含维护模式声明）与 Messages API 说明。不要给 TGI 编造 arXiv 编号；它是工程仓库，不是一篇会议论文。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TGI 把服务拆成 Rust router、Python model server 与 launcher；调度与 tokenize 在 router，推理与张量并行在 server，中间是 gRPC。</li><li>稳态调用是 <code>prefill</code>、<code>decode</code>、<code>filter_batch</code>；新请求的 prefill 会打断当前 decode batch，再合并继续。</li><li>连续批、SSE、OpenAI Messages API、OTel / Prometheus 是它留给后续引擎的接口习惯。</li><li>Tokenizer 与长度闸门在 router，不在 GPU 热路径上。</li><li>仓库处于维护模式；新部署应对照官方推荐的 vLLM / SGLang 等，而不是把旧镜像当成默认最优。</li><li>出处：Hugging Face <em>Text Generation Inference</em> 架构文档与项目说明。</li></ul>',14))])}const b=d(h,[["render",u]]);export{A as __pageData,b as default};
